import { Slider as BaseSlider } from '@base-ui/react/slider';
import type { ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { sliderVariants, type SliderVariantProps } from './slider.variants';

export interface SliderProps extends Omit<BaseSlider.Root.Props, 'className' | 'children'>, SliderVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Visible label; labels every thumb. Without it, pass `aria-label` (single) or `thumbLabels`. */
  label?: ReactNode;
  /** Accessible name of a single thumb when there is no visible label. */
  'aria-label'?: string;
  /** Per-thumb accessible names for range sliders, e.g. `['Minimum', 'Maximum']`. */
  thumbLabels?: string[];
  /** Show the formatted value next to the label. */
  showValue?: boolean;
  /** Custom value text; receives formatted strings and raw numbers. */
  formatValue?: (formatted: readonly string[], values: readonly number[]) => ReactNode;
}

function thumbCount(value: SliderProps['value'], defaultValue: SliderProps['defaultValue']) {
  const v = value ?? defaultValue;
  return Array.isArray(v) ? v.length : 1;
}

/**
 * Pick a number (or a range) on a track. Pass an array to `value` / `defaultValue` for a
 * range: one thumb per entry. Arrow keys step, Page Up/Down take `largeStep`, Home/End jump.
 */
export function Slider({
  size,
  label,
  'aria-label': ariaLabel,
  thumbLabels,
  showValue = false,
  formatValue = (formatted) => formatted.join(' – '),
  className,
  value,
  defaultValue,
  ...props
}: SliderProps) {
  const v = sliderVariants({ size });
  const count = thumbCount(value, defaultValue);
  return (
    <BaseSlider.Root className={cn(v.root(), className)} value={value} defaultValue={defaultValue} {...props}>
      {(label || showValue) && (
        <div className={v.header()}>
          {label && <BaseSlider.Label className={v.label()}>{label}</BaseSlider.Label>}
          {showValue && <BaseSlider.Value className={cn(v.value(), !label && 'ms-auto')}>{formatValue}</BaseSlider.Value>}
        </div>
      )}
      <BaseSlider.Control className={v.control()}>
        <BaseSlider.Track className={v.track()}>
          <BaseSlider.Indicator className={v.indicator()} />
          {Array.from({ length: count }, (_, i) => (
            <BaseSlider.Thumb
              key={i}
              index={i}
              aria-label={thumbLabels?.[i] ?? (count === 1 ? ariaLabel : undefined)}
              className={v.thumb()}
            />
          ))}
        </BaseSlider.Track>
      </BaseSlider.Control>
    </BaseSlider.Root>
  );
}

export { Slider, type SliderProps } from './Slider';
export { sliderVariants } from './slider.variants';
export { doc as sliderDoc } from './Slider.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const sliderVariants = tv({
  slots: {
    root: 'flex w-full flex-col gap-2 data-disabled:opacity-50',
    header: 'flex items-baseline justify-between gap-3',
    label: 'text-[13px] font-medium text-foreground',
    value: 'font-mono text-[12px] text-muted-foreground tabular-nums',
    control: 'flex w-full touch-none items-center select-none data-disabled:cursor-not-allowed',
    track: 'relative w-full rounded-full bg-secondary select-none',
    indicator: 'rounded-full bg-primary select-none',
    thumb: [
      'rounded-full border border-primary bg-background shadow-sm transition-[scale] select-none motion-reduce:transition-none',
      'has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-focus-ring',
      'data-dragging:scale-110 data-disabled:cursor-not-allowed',
    ],
  },
  variants: {
    size: {
      sm: { control: 'py-2', track: 'h-1', thumb: 'size-3.5' },
      md: { control: 'py-2.5', track: 'h-1.5', thumb: 'size-[18px]' },
    },
  },
  defaultVariants: { size: 'md' },
});

export type SliderVariantProps = VariantProps<typeof sliderVariants>;

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
